import type { WorksheetSnapshot } from '../../../shared/types';
import { cellKey } from './coordinates';

/**
 * Value a cell shows on screen, looked up by 0-based coordinates.
 *
 * Issue #3 decision D-A8 (contract increment A-3): the grid renderer and the
 * CSV export share this single seam, so "grid shows a calculated result while
 * the export writes the formula text" cannot happen. Sub-issue C replaces the
 * implementation of `worksheetDisplayValues` with its formula engine; this
 * module's identity is the interim, pre-C behaviour (formula cells show their
 * raw text).
 */
export type CellDisplayValue = (row: number, col: number) => string;

/** Identity seam: a cell shows exactly the raw text stored for it. */
export function worksheetDisplayValues(worksheet: WorksheetSnapshot): CellDisplayValue {
  const raw = new Map<string, string>();
  for (const [row, col, value] of worksheet.cells) {
    raw.set(cellKey(row, col), value);
  }
  return (row: number, col: number) => raw.get(cellKey(row, col)) ?? '';
}
